const log = createLogger('WorkerExecutor');

export const EXECUTOR_LEASE_OWNER = 'rivet-executor';

export type WorkerLeaseChoice = {
  leaseOwner: typeof EXECUTOR_LEASE_OWNER | 'rivet-host-agent';
  runtime?: WorkerInvocationAdapter;
  modelOverride?: string;
  callerModel?: string;
  summary: string;
};

export type WorkerModelChoice = Pick<
  WorkerLeaseChoice,
  'modelOverride' | 'callerModel'
>;

type WorkerModelSource = 'explicit' | 'caller' | 'fallback';

const workerModelFrom = (
  explicitModel: string | undefined,
  callerModel: string | undefined,
): { model?: string; source: WorkerModelSource } => {
  if (explicitModel) return { model: explicitModel, source: 'explicit' };
  if (callerModel) return { model: callerModel, source: 'caller' };
  return { source: 'fallback' };
};

export const chooseWorkerLeaseOwner = async (
  executor: WorkerExecutorService | undefined,
  args?: {
    initiator?: WorkItemInitiator;
    selection?: WorkerSelection;
    signal?: AbortSignal;
  },
): Promise<WorkerLeaseChoice> => {
  if (!executor && args?.initiator?.kind !== 'agent') {
    return { leaseOwner: 'rivet-host-agent', summary: 'host path' };
  }
  const decision = executor
    ? await executor.resolveRuntime(args)
    : await new WorkerRuntimeResolver({ runnerPaths: () => ({}) }).resolve(
        args,
      );
  if (decision.mode === 'executor') {
    return {
      leaseOwner: EXECUTOR_LEASE_OWNER,
      runtime: decision.adapter,
      ...(decision.modelOverride
        ? { modelOverride: decision.modelOverride }
        : {}),
      ...(decision.callerModel ? { callerModel: decision.callerModel } : {}),
      summary: `${decision.adapter.vendor} (${decision.source})`,
    };
  }
  if (decision.reason === 'initiating_host') {
    return {
      leaseOwner: 'rivet-host-agent',
      summary: 'initiating host (native permissions and approvals)',
    };
  }
  if (!executor)
    return { leaseOwner: 'rivet-host-agent', summary: 'host path' };
  const reasons = decision.diagnostics
    .map((d) => `${d.vendor}: ${d.reason.slice(0, 200)}`)
    .join('; ');
  return {
    leaseOwner: 'rivet-host-agent',
    summary: `host path${
      reasons
        ? ` (${reasons})`
        : ' (no runner binary declared by the invoking CLI or configured' +
          ' via runnerPaths — see `rivet status` for remediation)'
    }`,
  };
};

export const isWorkerExecutorEnabled = (
  env: NodeJS.ProcessEnv = process.env,
): boolean => {
  const flag = (env.RIVET_EXECUTOR ?? '').trim().toLowerCase();
  return flag !== '0' && flag !== 'false' && flag !== 'off';
};

type ReportCompleteArgs = {
  sessionId: string;
  workItemId: string;
  leaseId: string;
  attempt: number;
  status: 'succeeded' | 'failed';
  error?: { code: string; message: string; apiErrorStatus?: number };
  output?: unknown;
  tokensIn?: number;
  tokensOut?: number;
  model?: string;
  costUsd?: number;
  runtime?: import('./contracts').WorkerRuntimeInfo;
};

type WorkerUsage = {
  tokensIn?: number;
  tokensOut?: number;
  costUsd?: number;
};

type WorkerTerminationReason =
  | 'completed'
  | 'process_exit'
  | 'spawn_error'
  | 'timeout'
  | 'cancelled'
  | 'exception';

type WorkerOutcome = {
  status: 'succeeded' | 'failed';
  terminationReason: WorkerTerminationReason;
  exitCode: number | null;
  signal: NodeJS.Signals | null;
  message?: string;
  usage?: WorkerUsage;
  apiErrorStatus?: number;
};

const RATE_LIMIT_FAILURE = /rate.?limit|usage limit|\b429\b/i;
const MODEL_ERROR_PHRASE =
  /(unknown|invalid|unsupported|unrecognized)\s+model|model\s+(name\s+)?["'`]?[\w.:-]*["'`]?\s*(is\s+)?(not\s+(found|available|supported|recognized)|invalid|unknown|unavailable)|not_found_error[\s\S]{0,80}model|model[\s\S]{0,80}not_found_error|access\s+to\s+(the\s+)?(requested\s+)?model|model\s+access\s+(denied|revoked)|issue\s+with\s+the\s+selected\s+model|model\s*\([^)]{0,120}\)[\s\S]{0,80}(not\s+exist|not\s+have\s+access)/i;

export const isModelAvailabilityFailure = (
  message: string | undefined,
  model?: string,
): boolean => {
  if (!message) return false;
  if (RATE_LIMIT_FAILURE.test(message)) return true;
  if (MODEL_ERROR_PHRASE.test(message)) return true;
  if (
    model &&
    message.includes(model) &&
    /not\s+(found|available|supported)|invalid|unknown|unavailable|no\s+access/i.test(
      message,
    )
  ) {
    return true;
  }
  return false;
};

export const modelFailureReason = (
  message: string | undefined,
  apiErrorStatus?: number,
): 'model_rate_limited' | 'model_unavailable' => {
  if (apiErrorStatus === 429) return 'model_rate_limited';
  if (
    apiErrorStatus !== undefined &&
    MODEL_AVAILABILITY_STATUSES.has(apiErrorStatus)
  ) {
    return 'model_unavailable';
  }
  return message && /rate.?limit|usage limit|\b429\b/is.test(message)
    ? 'model_rate_limited'
    : 'model_unavailable';
};

const MODEL_AVAILABILITY_STATUSES = new Set([401, 403, 404, 429]);

const tierModelLabel = (tier: ExecutorWorkerTier): string =>
  ('model' in tier && tier.model) || `${tier.vendor}-default`;

const tierEffortLabel = (tier: ExecutorWorkerTier): string | null => {
  if (tier.vendor === 'claude') return tier.effort;
  if (tier.vendor === 'codex') return tier.reasoningEffort;
  return null;
};

const isRuntimeShapedFailure = (
  message: string | undefined,
  apiErrorStatus: number | undefined,
): boolean => {
  if (apiErrorStatus === 401 || apiErrorStatus === 403) return true;
  if (!message) return false;
  return /ENOENT|EACCES|unknown option|unexpected argument|command not found|credential|authentication|unauthorized|logged? ?in/i.test(
    message,
  );
};

export interface ExecutorOrchestrator {
  getHostWork(sessionId: string): HostVariantWorkItemSnapshot[];
  reportComplete(
    args: ReportCompleteArgs,
  ): Promise<{ requeuedForRegeneration?: boolean }>;
  requestWork(args: {
    sessionId: string;
    leaseOwner: string;
    workItemIds?: string[];
  }): {
    leaseId: string;
    leasedWorkItems: Array<{ id: string; attempt: number }>;
  };
}

export type WorkerSpawn = (args: {
  command: string;
  args: string[];
  cwd: string;
  prompt: string;
  env?: NodeJS.ProcessEnv;
}) => ReturnType<typeof spawn>;

const defaultSpawn: WorkerSpawn = ({ command, args, cwd, env }) =>
  spawn(command, args, {
    cwd,
    env: env ?? {},
    stdio: ['pipe', 'pipe', 'pipe'],
    detached: process.platform !== 'win32',
  });

export type WorkerExecutorOptions = {
  orchestrator: ExecutorOrchestrator;
  telemetry?: { track(event: string, props?: Record<string, unknown>): void };
  workerCommand?: string;
  workerModel?: string;
  workerEffort?: WorkerEffortLevel | string;
  referenceCreateModel?: string;
  referenceCreateEffort?: WorkerEffortLevel | string;
  fallbackModel?: string;
  timeoutMs?: number;
  maxConcurrent?: number;
  spawnWorker?: WorkerSpawn;
  configuredWorkerVendor?: () => string | undefined;
  workerVendorFallbackEnabled?: () => boolean;
  configuredWorkerModelFor?: (vendor: RunnerVendor) => string | undefined;
  configuredRunnerPaths?: () => Record<string, unknown> | undefined;
  preflightTimeoutMs?: number;
  spawnProbe?: PreflightSpawn;
  rateLimitRetryDelayMs?: number;
};

const DEFAULT_TIMEOUT_MS = 20 * 60 * 1000;
const DEFAULT_MAX_CONCURRENT = 3;
const DEFAULT_RATE_LIMIT_RETRY_DELAY_MS = 30_000;

const isExecutableImplementationItem = (
  item: HostVariantWorkItemSnapshot,
): item is HostVariantImplementationWorkItemSnapshot =>
  ('workspace' in item &&
    (item.kind === 'static_preview' || item.kind === 'refine_variant') &&
    item.workspace.kind === 'artifact_directory') ||
  ('workspace' in item &&
    item.kind === 'code_gen' &&
    item.workspace.kind === 'git_worktree');

export class WorkerExecutorService {
  private readonly orchestrator: ExecutorOrchestrator;
  private readonly telemetry?: WorkerExecutorOptions['telemetry'];
  private readonly workerCommand: string;
  private readonly workerModelOverride?: string;
  private readonly workerEffort: string;
  private readonly fallbackModel: string;
  private readonly referenceCreateModelOverride?: string;
  private readonly referenceCreateEffort: string;
  private readonly workerTierOverridden: boolean;
  private readonly referenceCreateTierOverridden: boolean;
  private readonly timeoutMs: number;
  private readonly rateLimitRetryDelayMs: number;
  private readonly childrenBySession = new Map<string, Set<number>>();
  private readonly cancelledSessions = new Set<string>();
  private readonly backoffWakersBySession = new Map<string, Set<() => void>>();
  private readonly maxConcurrent: number;
  private readonly spawnWorker: WorkerSpawn;
  private active = 0;
  private readonly waiters: Array<() => void> = [];
  private readonly resolver: WorkerRuntimeResolver;
  private readonly defaultAdapter: WorkerInvocationAdapter;
  private readonly configuredWorkerModelFor?: (
    vendor: RunnerVendor,
  ) => string | undefined;

  constructor(options: WorkerExecutorOptions) {
    this.orchestrator = options.orchestrator;
    this.telemetry = options.telemetry;
    this.workerCommand =
      options.workerCommand ?? process.env.RIVET_EXECUTOR_COMMAND ?? 'claude';
    this.workerTierOverridden = Boolean(
      options.workerModel ??
      options.workerEffort ??
      process.env.RIVET_EXECUTOR_MODEL ??
      process.env.RIVET_EXECUTOR_EFFORT,
    );
    this.referenceCreateTierOverridden = Boolean(
      options.referenceCreateModel ??
      options.referenceCreateEffort ??
      process.env.RIVET_EXECUTOR_REFERENCE_CREATE_MODEL ??
      process.env.RIVET_EXECUTOR_REFERENCE_CREATE_EFFORT,
    );
    this.workerModelOverride =
      options.workerModel ?? process.env.RIVET_EXECUTOR_MODEL;
    this.workerEffort =
      options.workerEffort ??
      process.env.RIVET_EXECUTOR_EFFORT ??
      RIVET_WORKER_DEFAULTS.effort;
    this.referenceCreateModelOverride =
      options.referenceCreateModel ??
      process.env.RIVET_EXECUTOR_REFERENCE_CREATE_MODEL;
    this.referenceCreateEffort =
      options.referenceCreateEffort ??
      process.env.RIVET_EXECUTOR_REFERENCE_CREATE_EFFORT ??
      RIVET_WORKER_REFERENCE_CREATE_DEFAULTS.effort;
    this.fallbackModel =
      options.fallbackModel ??
      process.env.RIVET_EXECUTOR_FALLBACK_MODEL ??
      'claude-sonnet-5';
    this.timeoutMs =
      options.timeoutMs ??
      Number(process.env.RIVET_EXECUTOR_TIMEOUT_MS ?? DEFAULT_TIMEOUT_MS);
    this.rateLimitRetryDelayMs =
      options.rateLimitRetryDelayMs ??
      Number(
        process.env.RIVET_EXECUTOR_RATE_LIMIT_RETRY_DELAY_MS ??
          DEFAULT_RATE_LIMIT_RETRY_DELAY_MS,
      );
    this.maxConcurrent = options.maxConcurrent ?? DEFAULT_MAX_CONCURRENT;
    this.spawnWorker = options.spawnWorker ?? defaultSpawn;
    this.defaultAdapter = makeClaudeAdapter(this.workerCommand);
    this.configuredWorkerModelFor = options.configuredWorkerModelFor;
    const resolverOptions: WorkerRuntimeResolverOptions = {
      configuredVendor: options.configuredWorkerVendor,
      crossVendorFallback: options.workerVendorFallbackEnabled,
      configuredModelFor: options.configuredWorkerModelFor,
      runnerPaths: () => ({
        ...parseCallerRunnerPaths(),
        ...verifiedRunnerPaths(options.configuredRunnerPaths?.(), 'config'),
      }),
      probeModelFallback: {
        fallbackModel: () => this.fallbackModel,
        isModelAvailabilityFailure: ({ message, apiErrorStatus, model }) =>
          MODEL_AVAILABILITY_STATUSES.has(apiErrorStatus ?? -1) ||
          isModelAvailabilityFailure(message, model),
      },
      telemetry: this.telemetry,
      ...(options.preflightTimeoutMs !== undefined
        ? { probeTimeoutMs: options.preflightTimeoutMs }
        : {}),
      ...(options.spawnProbe ? { spawnProbe: options.spawnProbe } : {}),
    };
    this.resolver = new WorkerRuntimeResolver(resolverOptions);
  }

  async resolveRuntime(args?: {
    initiator?: WorkItemInitiator;
    selection?: WorkerSelection;
    signal?: AbortSignal;
  }): Promise<WorkerRuntimeDecision> {
    return this.resolver.resolve(args);
  }

  cancelSession(sessionId: string): void {
    this.cancelledSessions.add(sessionId);
    for (const pid of this.childrenBySession.get(sessionId) ?? []) {
      this.killTree(pid);
    }
    this.childrenBySession.delete(sessionId);
    for (const wake of this.backoffWakersBySession.get(sessionId) ?? []) {
      wake();
    }
    this.backoffWakersBySession.delete(sessionId);
  }

  private backoff(sessionId: string, ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      const wakers =
        this.backoffWakersBySession.get(sessionId) ?? new Set<() => void>();
      this.backoffWakersBySession.set(sessionId, wakers);
      const wake = (): void => {
        clearTimeout(timer);
        wakers.delete(wake);
        if (wakers.size === 0) this.backoffWakersBySession.delete(sessionId);
        resolve();
      };
      wakers.add(wake);
      const timer = setTimeout(wake, ms);
    });
  }

  async run(
    sessionId: string,
    workItemIds: string[],
    lease?: { leaseId: string; items: Array<{ id: string; attempt: number }> },
    runtime?: WorkerInvocationAdapter,
    models: WorkerModelChoice = {},
  ): Promise<void> {
    this.cancelledSessions.delete(sessionId);
    const adapter = runtime ?? this.defaultAdapter;
    const claimed = new Set(workItemIds);
    const claimedItems = this.orchestrator
      .getHostWork(sessionId)
      .filter((item) => claimed.has(item.workId));
    const runnable = claimedItems.filter(isExecutableImplementationItem);
    const stranded = claimedItems.filter(
      (item) => !runnable.some((candidate) => candidate.workId === item.workId),
    );
    const unseen = workItemIds.filter(
      (workItemId) => !claimedItems.some((item) => item.workId === workItemId),
    );
    await Promise.all([
      ...runnable.map((item) =>
        adapter.vendor === 'cursor'
          ? this.reportSafely(sessionId, {
              workItemId: item.workId,
              leaseId: item.leaseId,
              attempt: item.attempt,
              status: 'failed',
              error: {
                code: 'EXECUTOR_RUNTIME_UNSUPPORTED',
                message: CURSOR_NATIVE_WORKER_REQUIRED,
              },
            })
          : this.runOne(sessionId, item, { retried: false }, adapter, models),
      ),
      ...stranded.map((item) =>
        this.reportSafely(sessionId, {
          workItemId: item.workId,
          leaseId: item.leaseId,
          attempt: item.attempt,
          status: 'failed',
          error: {
            code: 'EXECUTOR_UNSUPPORTED_ITEM',
            message: `executor cannot run kind=${item.kind}`,
          },
        }),
      ),
      ...unseen.map((workItemId) => {
        if (!lease) {
          log.error(
            `executor claimed ${workItemId} but it is missing from the session snapshot and no lease context was provided — item may be stranded until lease expiry`,
          );
          return Promise.resolve({});
        }
        return this.reportSafely(sessionId, {
          workItemId,
          leaseId: lease.leaseId,
          attempt:
            lease.items.find((item) => item.id === workItemId)?.attempt ?? 1,
          status: 'failed',
          error: {
            code: 'EXECUTOR_ITEM_UNSEEN',
            message:
              'claimed work item missing from the session snapshot at run time',
          },
        });
      }),
    ]);
  }

  private async reportSafely(
    sessionId: string,
    args: Omit<ReportCompleteArgs, 'sessionId'>,
  ): Promise<{ requeuedForRegeneration?: boolean }> {
    try {
      return await this.orchestrator.reportComplete({ sessionId, ...args });
    } catch (error) {
      const message = errorMessage(error);
      if (args.status === 'failed') {
        log.warn(
          `executor failed-report rejected for ${args.workItemId}`,
          error,
        );
        return {};
      }
      log.warn(
        `executor success report rejected for ${args.workItemId} — recording failure`,
        error,
      );
      try {
        return await this.orchestrator.reportComplete({
          sessionId,
          workItemId: args.workItemId,
          leaseId: args.leaseId,
          attempt: args.attempt,
          status: 'failed',
          error: { code: 'EXECUTOR_ARTIFACT_INVALID', message },
          ...(args.runtime ? { runtime: args.runtime } : {}),
        });
      } catch (secondError) {
        log.warn(
          `executor terminal-failure report rejected for ${args.workItemId}`,
          secondError,
        );
        return {};
      }
    }
  }

  private workerTierFor(
    item: HostVariantImplementationWorkItemSnapshot,
    vendor: RunnerVendor,
    models: WorkerModelChoice,
  ): { tier: ExecutorWorkerTier; modelSource: WorkerModelSource } {
    const referenceBacked = Boolean(
      item.contextFiles?.length || item.contextBundlePath,
    );
    const isReferenceCreate = item.mode === 'create' && referenceBacked;
    const configured = this.configuredWorkerModelFor?.(vendor);
    if (vendor !== 'claude') {
      const fidelity = isReferenceCreate
        ? 'high'
        : isWorkerFidelity(item.fidelity)
          ? item.fidelity
          : DEFAULT_WORKER_FIDELITY;
      const base = EXECUTOR_FIDELITY_TIERS[vendor][fidelity];
      const { model, source } = workerModelFrom(
        process.env.RIVET_EXECUTOR_MODEL ?? models.modelOverride ?? configured,
        models.callerModel,
      );
      return { tier: model ? { ...base, model } : base, modelSource: source };
    }
    const overridden = isReferenceCreate
      ? this.referenceCreateTierOverridden
      : this.workerTierOverridden;
    const laneModelOverride = isReferenceCreate
      ? this.referenceCreateModelOverride
      : this.workerModelOverride;
    const { model, source } = workerModelFrom(
      models.modelOverride ?? laneModelOverride ?? configured,
      models.callerModel,
    );
    if (!overridden && isWorkerFidelity(item.fidelity)) {
      const base = EXECUTOR_FIDELITY_TIERS.claude[item.fidelity];
      return { tier: model ? { ...base, model } : base, modelSource: source };
    }
    const lane = isReferenceCreate
      ? {
          model: RIVET_WORKER_REFERENCE_CREATE_DEFAULTS.model,
          effort: this.referenceCreateEffort,
        }
      : { model: RIVET_WORKER_DEFAULTS.model, effort: this.workerEffort };
    return {
      tier: {
        vendor: 'claude',
        model: model ?? lane.model,
        effort: lane.effort as WorkerEffortLevel,
      },
      modelSource: source,
    };
  }

  private async runOne(
    sessionId: string,
    item: HostVariantImplementationWorkItemSnapshot,
    state: { retried: boolean },
    adapter: WorkerInvocationAdapter,
    models: WorkerModelChoice,
  ): Promise<void> {
    await this.acquire();
    const startedAt = Date.now();
    const { tier, modelSource } = this.workerTierFor(
      item,
      adapter.vendor,
      models,
    );
    if (modelSource === 'fallback') {
      log.info(
        `worker ${item.workId}: caller model unknown — running ${adapter.vendor} default model ${tierModelLabel(tier)}`,
      );
    }
    this.telemetry?.track('agent_variants.executor_worker_started', {
      source: 'mcp',
      sessionId,
      workItemId: item.workId,
      vendor: adapter.vendor,
      model: tierModelLabel(tier),
      model_source: modelSource,
      effort: tierEffortLabel(tier),
      fidelity: item.fidelity ?? null,
      attempt: item.attempt,
    });
    let outcome: WorkerOutcome;
    let ranModel = tierModelLabel(tier);
    try {
      outcome = await this.spawnAndWait(sessionId, item, adapter, tier);
      if (
        outcome.status === 'failed' &&
        !isWorkerPermissionFailure(outcome.message) &&
        outcome.usage?.tokensOut === 0 &&
        (outcome.apiErrorStatus === 429 ||
          (outcome.message !== undefined &&
            RATE_LIMIT_FAILURE.test(outcome.message)))
      ) {
        this.telemetry?.track(
          'agent_variants.executor_worker_rate_limit_retry',
          {
            source: 'mcp',
            sessionId,
            workItemId: item.workId,
            vendor: adapter.vendor,
            model: tierModelLabel(tier),
            delayMs: this.rateLimitRetryDelayMs,
          },
        );
        await this.backoff(sessionId, this.rateLimitRetryDelayMs);
        if (!this.cancelledSessions.has(sessionId)) {
          outcome = await this.spawnAndWait(sessionId, item, adapter, tier);
        }
      }
      const workspacePristine = (outcome.usage?.tokensOut ?? 0) === 0;
      if (
        outcome.status === 'failed' &&
        !this.cancelledSessions.has(sessionId) &&
        !isWorkerPermissionFailure(outcome.message) &&
        adapter.supportsModelFallback &&
        models.modelOverride === undefined &&
        tier.vendor === 'claude' &&
        tier.model !== this.fallbackModel &&
        workspacePristine &&
        (MODEL_AVAILABILITY_STATUSES.has(outcome.apiErrorStatus ?? -1) ||
          isModelAvailabilityFailure(outcome.message, tier.model))
      ) {
        this.telemetry?.track('agent_variants.executor_worker_model_fallback', {
          source: 'mcp',
          sessionId,
          workItemId: item.workId,
          fromModel: tier.model,
          toModel: this.fallbackModel,
          reason: modelFailureReason(outcome.message, outcome.apiErrorStatus),
        });
        ranModel = this.fallbackModel;
        outcome = await this.spawnAndWait(sessionId, item, adapter, {
          vendor: 'claude',
          model: this.fallbackModel,
          effort: tier.effort,
        });
      }
    } catch (error) {
      outcome = {
        status: 'failed',
        terminationReason: 'exception',
        exitCode: null,
        signal: null,
        message:
          getGenerationCapacityError(error)?.message ?? errorMessage(error),
      };
    } finally {
      this.release();
    }
    if (outcome.status === 'failed' && this.cancelledSessions.has(sessionId)) {
      outcome = { ...outcome, terminationReason: 'cancelled' };
    }
    this.telemetry?.track('agent_variants.executor_worker_exited', {
      source: 'mcp',
      sessionId,
      workItemId: item.workId,
      durationMs: Date.now() - startedAt,
      status: outcome.status,
      worker_status: outcome.status,
      exit_code: outcome.exitCode,
      term_signal: outcome.signal,
      failure_reason:
        outcome.status === 'failed' ? outcome.terminationReason : null,
      api_error_status: outcome.apiErrorStatus ?? null,
      tokensIn: outcome.usage?.tokensIn ?? null,
      tokensOut: outcome.usage?.tokensOut ?? null,
      costUsd: outcome.usage?.costUsd ?? null,
    });
    if (outcome.status === 'failed') {
      log.error(
        `worker failed (workItem ${item.workId}, attempt ${item.attempt}, ` +
          `vendor ${adapter.vendor}, model ${ranModel}` +
          (outcome.apiErrorStatus !== undefined
            ? `, apiStatus ${outcome.apiErrorStatus}`
            : '') +
          `): ${outcome.message ?? 'no failure detail captured'}`,
      );
      if (isRuntimeShapedFailure(outcome.message, outcome.apiErrorStatus)) {
        this.resolver.markUnhealthy(
          adapter.vendor,
          outcome.message ?? 'worker failed',
        );
      }
    }

    const effort = tierEffortLabel(tier);
    const result = await this.reportSafely(sessionId, {
      workItemId: item.workId,
      leaseId: item.leaseId,
      attempt: item.attempt,
      status: outcome.status,
      ...(outcome.usage?.tokensIn !== undefined
        ? { tokensIn: outcome.usage.tokensIn }
        : {}),
      ...(outcome.usage?.tokensOut !== undefined
        ? { tokensOut: outcome.usage.tokensOut }
        : {}),
      ...(outcome.usage?.costUsd !== undefined
        ? { costUsd: outcome.usage.costUsd }
        : {}),
      model: ranModel,
      runtime: {
        vendor: adapter.vendor,
        model: ranModel,
        ...(effort ? { effort } : {}),
      },
      ...(outcome.status === 'succeeded' &&
      item.kind === 'code_gen' &&
      item.workspace.kind === 'git_worktree'
        ? {
            output: {
              worktreePath: item.workspace.rootPath,
              changedFiles: [],
            },
          }
        : {}),
      ...(outcome.status === 'failed'
        ? {
            error: {
              code: 'EXECUTOR_WORKER_FAILED',
              message: outcome.message ?? 'worker failed',
              ...(outcome.apiErrorStatus !== undefined
                ? { apiErrorStatus: outcome.apiErrorStatus }
                : {}),
            },
          }
        : {}),
    });

    if (result.requeuedForRegeneration && !state.retried) {
      try {
        const renewedLease = this.orchestrator.requestWork({
          sessionId,
          workItemIds: [item.workId],
          leaseOwner: EXECUTOR_LEASE_OWNER,
        });
        const renewed = this.orchestrator
          .getHostWork(sessionId)
          .filter(isExecutableImplementationItem)
          .find((candidate) => candidate.workId === item.workId);
        if (renewed) {
          await this.runOne(
            sessionId,
            renewed,
            { retried: true },
            adapter,
            models,
          );
          return;
        }
        const renewedAttempt =
          renewedLease.leasedWorkItems.find(
            (leased) => leased.id === item.workId,
          )?.attempt ?? item.attempt + 1;
        await this.reportSafely(sessionId, {
          workItemId: item.workId,
          leaseId: renewedLease.leaseId,
          attempt: renewedAttempt,
          status: 'failed',
          error: {
            code: 'EXECUTOR_REQUEUE_LOST',
            message: 'requeued item was not re-runnable by the executor',
          },
        });
      } catch (error) {
        log.warn(`executor requeue retry failed for ${item.workId}`, error);
        try {
          const salvageLease = this.orchestrator.requestWork({
            sessionId,
            workItemIds: [item.workId],
            leaseOwner: EXECUTOR_LEASE_OWNER,
          });
          const salvageAttempt =
            salvageLease.leasedWorkItems.find(
              (leased) => leased.id === item.workId,
            )?.attempt ?? item.attempt + 1;
          await this.reportSafely(sessionId, {
            workItemId: item.workId,
            leaseId: salvageLease.leaseId,
            attempt: salvageAttempt,
            status: 'failed',
            error: {
              code: 'EXECUTOR_REQUEUE_LOST',
              message:
                'executor requeue retry failed; recording terminal failure',
            },
          });
        } catch (salvageError) {
          log.error(
            `executor could not terminal-fail requeued ${item.workId} — item may be stranded until lease expiry`,
            salvageError,
          );
        }
      }
    }
  }

  private async spawnAndWait(
    sessionId: string,
    item: HostVariantImplementationWorkItemSnapshot,
    adapter: WorkerInvocationAdapter,
    tier: ExecutorWorkerTier,
  ): Promise<WorkerOutcome> {
    const prompt = renderWorkItemBriefing(item, { completion: 'executor' });
    const args = adapter.buildArgs(tier);
    const illustrations = guidanceAttachments(item.guidance ?? []);
    for (const image of illustrations) await readGuidanceImage(image);
    if (adapter.vendor === 'codex' && illustrations.length)
      args.splice(
        args.length - 1,
        0,
        ...illustrations.flatMap((image) => ['--image', image.path]),
      );
    if (adapter.promptDelivery === 'argv') args.push(prompt);
    const child = this.spawnWorker({
      command: adapter.binary,
      args,
      cwd:
        item.workspace.kind === 'git_worktree'
          ? item.workspace.projectPath
          : item.workspace.rootPath,
      prompt,
      env: adapter.spawnEnv(),
    });
    const childPid = child.pid;
    if (childPid) {
      const children =
        this.childrenBySession.get(sessionId) ?? new Set<number>();
      children.add(childPid);
      this.childrenBySession.set(sessionId, children);
      child.on('close', () => children.delete(childPid));
    }
    let inputError: Error | undefined;
    child.stdin?.on('error', (error: Error) => {
      inputError = error;
    });
    if (adapter.promptDelivery === 'stdin') {
      child.stdin?.write(prompt);
    }
    child.stdin?.end();
    let stderrTail = '';
    child.stderr?.on('data', (chunk: Buffer) => {
      stderrTail = (stderrTail + chunk.toString()).slice(-2000);
    });
    let stdoutTail = '';
    child.stdout?.on('data', (chunk: Buffer) => {
      stdoutTail = (stdoutTail + chunk.toString()).slice(-131072);
    });

    return new Promise((resolve) => {
      const timer = setTimeout(() => {
        this.killTree(child.pid);
        resolve({
          status: 'failed',
          terminationReason: 'timeout',
          exitCode: null,
          signal: null,
          message: `worker timed out after ${this.timeoutMs}ms`,
        });
      }, this.timeoutMs);
      child.on('error', (error) => {
        clearTimeout(timer);
        resolve({
          status: 'failed',
          terminationReason: 'spawn_error',
          exitCode: null,
          signal: null,
          message: getGenerationCapacityError(error)?.message ?? error.message,
        });
      });
      child.on('close', (code, signal) => {
        clearTimeout(timer);
        const { usage, resultText, apiErrorStatus, isFailed, error } =
          adapter.parseResult(stdoutTail);
        if (code === 0 && !isFailed && !inputError) {
          resolve({
            status: 'succeeded',
            terminationReason: 'completed',
            exitCode: code,
            signal,
            ...(usage ? { usage } : {}),
          });
          return;
        }
        const terminationReason = this.cancelledSessions.has(sessionId)
          ? 'cancelled'
          : 'process_exit';
        const resultDetail = resultText
          ? ` | result: ${resultText.slice(-500)}`
          : '';
        const processFailure = `worker exited ${code}: ${stderrTail.slice(-400)}${resultDetail}`;
        const capacityError = isWorkerPermissionFailure(processFailure)
          ? undefined
          : getGenerationCapacityError({
              message: stderrTail,
              result: isFailed ? resultText : undefined,
              status: apiErrorStatus,
              error,
            });
        resolve({
          status: 'failed',
          terminationReason,
          exitCode: code,
          signal,
          message:
            capacityError?.message ??
            (inputError
              ? `worker input delivery failed: ${inputError.message}; ${processFailure}`
              : processFailure),
          ...(usage ? { usage } : {}),
          ...(apiErrorStatus !== undefined ? { apiErrorStatus } : {}),
        });
      });
    });
  }

  private killTree(pid: number | undefined): void {
    if (!pid) return;
    try {
      if (process.platform === 'win32') {
        process.kill(pid, 'SIGKILL');
        return;
      }
      process.kill(-pid, 'SIGKILL');
    } catch {
      try {
        process.kill(pid, 'SIGKILL');
      } catch {}
    }
  }

  private acquire(): Promise<void> {
    if (this.active < this.maxConcurrent) {
      this.active += 1;
      return Promise.resolve();
    }
    return new Promise((resolve) =>
      this.waiters.push(() => {
        this.active += 1;
        resolve();
      }),
    );
  }

  private release(): void {
    this.active -= 1;
    const next = this.waiters.shift();
    if (next) next();
  }
}
